class _OsceStation {
  final String id,specialty,title,category,scenario,task,checklistText,critical,feedback;
  const _OsceStation(this.id,this.specialty,this.title,this.category,this.scenario,this.task,this.checklistText,this.critical,this.feedback);
  List<String> get points=>checklistText.split('; ').where((x)=>x.isNotEmpty).toList();
  factory _OsceStation.parse(String line){final p=line.split('|');return _OsceStation(p[0],p[1],p[2],p[3],p[4],p[5],p[6],p[7],p[8]);}
}
